package com.osrssettlement;

final class ProfileGuard
{
	private volatile long generation;
	private volatile boolean running;

	long start()
	{
		generation++;
		running = true;
		return generation;
	}

	void stop()
	{
		running = false;
		generation++;
	}

	void advance()
	{
		generation++;
	}

	long current()
	{
		return generation;
	}

	boolean isRunning()
	{
		return running;
	}

	boolean accepts(long selected)
	{
		return running && selected == generation;
	}

	View newView()
	{
		return new View();
	}

	final class View
	{
		private volatile long displayed = -1;

		boolean show(long selected)
		{
			if (!accepts(selected))
			{
				return false;
			}
			displayed = selected;
			return true;
		}

		long selected()
		{
			return displayed;
		}
	}
}

package com.osrssettlement;

import com.google.gson.Gson;
import com.osrssettlement.engine.SettlementEngine;
import com.osrssettlement.model.BossTier;
import com.osrssettlement.model.Building;
import com.osrssettlement.model.ExpeditionId;
import com.osrssettlement.model.ClueTier;
import com.osrssettlement.model.Resource;
import com.osrssettlement.model.SettlementState;
import com.osrssettlement.persistence.SettlementStore;
import com.osrssettlement.tracking.BossRegistry;
import com.osrssettlement.tracking.ChatEventParser;
import com.osrssettlement.tracking.XpTracker;
import com.osrssettlement.ui.SettlementActions;
import com.osrssettlement.ui.SettlementPanel;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "OSRS Settlement",
	description = "Build a settlement in the sidebar, fuelled by your skilling, Slayer, bossing and clue scrolls",
	tags = {"settlement", "town", "minigame", "building", "bounty", "xp", "boss", "clue"}
)
public class SettlementPlugin extends Plugin
{
	private static final int SAVE_INTERVAL_TICKS = 100;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SettlementStore store;

	@Inject
	private Gson gson;

	private final XpTracker xpTracker = new XpTracker();
	private final Random random = new Random();

	private SettlementPanel panel;
	private NavigationButton navButton;
	private final ProfileGuard profiles = new ProfileGuard();
	private PanelActions panelActions;
	private final Map<String, PendingSave> pending = new HashMap<>();
	private SettlementStore.Session session;
	private String protectionMessage;

	private static final class PendingSave
	{
		private final SettlementStore.Session session;
		private final SettlementEngine engine;
		private final String json;

		private PendingSave(SettlementStore.Session session, SettlementEngine engine, String json)
		{
			this.session = session;
			this.engine = engine;
			this.json = json;
		}
	}

	private SettlementEngine engine;
	private String profileKey;
	private boolean dirty;
	private boolean uiDirty;
	private int ticksSinceSave;

	@Override
	protected synchronized void startUp()
	{
		long startupGeneration = profiles.start();
		panelActions = new PanelActions();
		panel = new SettlementPanel(itemManager, panelActions);
		navButton = NavigationButton.builder()
			.tooltip("Settlement")
			.icon(ImageUtil.loadImageResource(SettlementPlugin.class, "icon.png"))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		clientThread.invoke(() ->
		{
			synchronized (SettlementPlugin.this)
			{
				if (!profiles.accepts(startupGeneration))
				{
					return;
				}
				loadProfile(configManager.getRSProfileKey());
				if (client.getGameState() == GameState.LOGGED_IN)
				{
					xpTracker.snapshot(client::getSkillExperience);
				}
				else
				{
					xpTracker.reset();
				}
			}
		});
	}

	@Override
	protected synchronized void shutDown()
	{
		profiles.stop();
		flushPending();
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;

		engine = null;
		profileKey = null;
		session = null;
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		long selected = profiles.current();
		clientThread.invoke(() ->
		{
			synchronized (SettlementPlugin.this)
			{
				if (!profiles.accepts(selected))
				{
					return;
				}
				saveNow();
				loadProfile(configManager.getRSProfileKey());
				xpTracker.reset();
			}
		});
	}

	@Subscribe
	public synchronized void onClientShutdown(ClientShutdown event)
	{
		profiles.stop();
		flushPending();
	}

	private void flushPending()
	{
		for (PendingSave saved : new ArrayList<>(pending.values()))
		{
			if (saved.json == null)
			{
				log.warn("Settlement has invalid unsaved progress; shutdown will not overwrite saved data");
				continue;
			}
			try
			{
				store.save(saved.session, saved.json);
				pending.remove(saved.session.getProfileKey());
			}
			catch (RuntimeException exception)
			{
				log.warn("Settlement progress could not be saved; pending progress remains in memory", exception);
			}
		}
	}

	@Subscribe
	public synchronized void onGameStateChanged(GameStateChanged event)
	{
		if (!profiles.isRunning())
		{
			return;
		}
		switch (event.getGameState())
		{
			case LOGGING_IN:
			case HOPPING:
				xpTracker.reset();
				break;
			case LOGIN_SCREEN:
				xpTracker.reset();
				saveNow();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public synchronized void onGameTick(GameTick event)
	{
		if (!profiles.isRunning())
		{
			return;
		}
		if (xpTracker.tick())
		{
			xpTracker.snapshot(client::getSkillExperience);
		}

		if (engine == null || protectionMessage != null)
		{
			return;
		}

		engine.onTick();
		markChanged();

		if (++ticksSinceSave >= SAVE_INTERVAL_TICKS)
		{
			saveNow();
		}
		if (uiDirty)
		{
			pushUi();
		}
	}

	@Subscribe
	public synchronized void onStatChanged(StatChanged event)
	{
		if (!profiles.isRunning())
		{
			return;
		}
		int gained = xpTracker.onStatChanged(event.getSkill(), event.getXp());
		if (gained > 0 && engine != null && protectionMessage == null)
		{
			engine.onXp(event.getSkill(), gained);
			markChanged();
		}
	}

	@Subscribe
	public synchronized void onChatMessage(ChatMessage event)
	{
		if (!profiles.isRunning() || protectionMessage != null || engine == null
			|| (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM))
		{
			return;
		}

		String message = event.getMessage();
		String boss = ChatEventParser.parseKillCount(message);
		if (boss != null)
		{
			BossTier tier = BossRegistry.tierOf(boss);
			if (tier != null)
			{
				engine.onBossKill(boss, tier, BossRegistry.isRaid(boss));
				markChanged();
			}
			return;
		}

		ClueTier clue = ChatEventParser.parseClue(message);
		if (clue != null)
		{
			engine.onClueCompleted(clue);
			markChanged();
		}
	}

	private void loadProfile(String key)
	{
		profiles.advance();
		profileKey = key;
		engine = null;
		session = null;
		dirty = false;
		ticksSinceSave = 0;
		protectionMessage = null;
		if (key == null)
		{
			pushUi();
			return;
		}
		PendingSave retained = pending.get(key);
		if (retained != null)
		{
			session = retained.session;
			engine = retained.engine;
			dirty = true;
			protectionMessage = "Unsaved progress is retained for this account. Retry saving before continuing.";
			pushUi();
			return;
		}
		session = store.load(key);
		if (!session.isWritable())
		{
			protectionMessage = session.getMessage();
		}
		else
		{
			try
			{
				SettlementState state = session.getStatus() == SettlementStore.Status.NEW
					? SettlementEngine.newSettlement() : session.getState();
				SettlementEngine candidate = new SettlementEngine(state, random);
				store.snapshot(candidate.getState());
				engine = candidate;
				if (session.getStatus() == SettlementStore.Status.NEW)
				{
					markChanged();
					saveNow();
				}
			}
			catch (RuntimeException exception)
			{
				log.warn("Unable to initialize settlement; saved progress was preserved", exception);
				protectionMessage = "Saved progress could not be initialized safely. It has not been replaced.";
			}
		}
		pushUi();
	}

	private void markChanged()
	{
		dirty = true;
		uiDirty = true;
		String json = null;
		try
		{
			json = store.snapshot(engine.getState());
		}
		catch (RuntimeException exception)
		{
			log.warn("Unable to prepare settlement progress for saving", exception);
			protectionMessage = "Progress could not be safely saved. Your existing save has been preserved.";
		}
		pending.put(profileKey, new PendingSave(session, engine, json));
		if (protectionMessage != null)
		{
			pushUi();
		}
	}

	private void saveNow()
	{
		if (!dirty || engine == null || profileKey == null)
		{
			return;
		}
		try
		{
			String json = store.snapshot(engine.getState());
			pending.put(profileKey, new PendingSave(session, engine, json));
			store.save(session, json);
			pending.remove(profileKey);
			dirty = false;
			ticksSinceSave = 0;
			protectionMessage = null;
		}
		catch (RuntimeException exception)
		{
			log.warn("Unable to save settlement progress", exception);
			protectionMessage = "Progress is unsaved and retained in memory. "
				+ "Retry before closing RuneLite. Changed or incompatible saved data will not be overwritten.";
			pushUi();
		}
	}

	private void pushUi()
	{
		pushUi(null);
	}

	private void pushUi(String rewardText)
	{
		uiDirty = false;
		SettlementPanel target = panel;
		if (target == null || !target.isActive() && protectionMessage == null && engine != null)
		{
			return;
		}

		long selected = profiles.current();
		PanelActions actions = panelActions;
		String message = protectionMessage;
		SettlementState snapshot = engine == null || message != null ? null
			: gson.fromJson(gson.toJson(engine.getState()), SettlementState.class);
		String restoreSnapshot = snapshot == null ? null : store.restorableSnapshot(session);
		SwingUtilities.invokeLater(() ->
		{
			if (panel != target || !actions.view.show(selected))
			{
				return;
			}
			actions.restoreSnapshot = restoreSnapshot;
			if (message != null)
			{
				target.showProtected(message);
			}
			else
			{
				target.update(snapshot, restoreSnapshot != null);
			}
			if (rewardText != null && message == null)
			{
				target.showBountyReward(rewardText);
			}
		});
	}

	private class PanelActions implements SettlementActions
	{
		private final ProfileGuard.View view = profiles.newView();
		private volatile String restoreSnapshot;

		private void enqueue(long selected, Runnable action, boolean gameplay)
		{
			clientThread.invoke(() ->
			{
				synchronized (SettlementPlugin.this)
				{
					if (PanelActions.this != panelActions || !profiles.accepts(selected)
						|| gameplay && (engine == null || protectionMessage != null || !session.isWritable()))
					{
						return;
					}
					action.run();
				}
			});
		}

		@Override
		public void upgrade(Building building)
		{
			enqueue(view.selected(), () ->
			{
				if (engine != null && engine.upgrade(building).isOk())
				{
					markChanged();
					saveNow();
				}
				pushUi();
			}, true);
		}

		@Override
		public void claimBounty(int bountyId)
		{
			runRewardAction(() -> engine.claimBounty(bountyId));
		}

		@Override
		public void claimExpedition(ExpeditionId expeditionId)
		{
			runRewardAction(() -> engine.claimExpedition(expeditionId));
		}

		@Override
		public void tradeKeldagrimConsortium(Resource input, Resource output)
		{
			runRewardAction(() -> engine.tradeAtKeldagrimConsortium(input, output));
		}

		@Override
		public void setLabourPaused(boolean paused)
		{
			enqueue(view.selected(), () ->
			{
				if (engine != null && engine.getState().isLabourPaused() != paused)
				{
					engine.setLabourPaused(paused);
					markChanged();
					saveNow();
				}
				pushUi();
			}, true);
		}

		// action returns reward text, or null when nothing changed
		private void runRewardAction(Supplier<String> action)
		{
			enqueue(view.selected(), () ->
			{
				String rewardText = engine == null ? null : action.get();
				if (rewardText != null)
				{
					markChanged();
					saveNow();
				}
				pushUi(rewardText);
			}, true);
		}

		@Override
		public void reset()
		{
			prepareReset().run();
		}

		@Override
		public Runnable prepareReset()
		{
			long selected = view.selected();
			return () -> enqueue(selected, () ->
			{
				try
				{
					SettlementEngine replacement = new SettlementEngine(SettlementEngine.newSettlement(), random);
					store.reset(session, store.snapshot(engine.getState()), store.snapshot(replacement.getState()));
					engine = replacement;
					pending.remove(profileKey);
					dirty = false;
					ticksSinceSave = 0;
					xpTracker.reset();
					profiles.advance();
				}
				catch (RuntimeException exception)
				{
					log.warn("Settlement reset was cancelled", exception);
					dirty = true;
					markChanged();
					protectionMessage = "Reset could not be completed. " + exception.getMessage();
				}
				pushUi();
			}, true);
		}

		@Override
		public Runnable prepareRestore()
		{
			long selected = view.selected();
			String backup = restoreSnapshot;
			return () -> enqueue(selected, () ->
			{
				try
				{
					if (backup == null)
					{
						throw new IllegalStateException("No valid restore point is available.");
					}
					SettlementEngine replacement = new SettlementEngine(store.restoreState(backup), random);
					store.snapshot(replacement.getState());
					store.restore(session, store.snapshot(engine.getState()), backup);
					engine = replacement;
					pending.remove(profileKey);
					dirty = false;
					ticksSinceSave = 0;
					xpTracker.reset();
					profiles.advance();
				}
				catch (RuntimeException exception)
				{
					log.warn("Settlement restore was cancelled", exception);
					if (!session.isWritable())
					{
						markChanged();
						protectionMessage = "Restore could not be safely rolled back. Retry before closing RuneLite.";
					}
					else
					{
						SettlementPanel target = panel;
						SwingUtilities.invokeLater(() ->
						{
							if (panel == target && profiles.accepts(selected))
							{
								target.showRestoreError(exception.getMessage());
							}
						});
					}
				}
				pushUi();
			}, true);
		}

		@Override
		public void retry()
		{
			enqueue(view.selected(), () ->
			{
				if (dirty)
				{
					try
					{
						store.recoverRestore(session);
					}
					catch (RuntimeException exception)
					{
						log.warn("Settlement restore recovery is still pending", exception);
						pushUi();
						return;
					}
					saveNow();
					xpTracker.reset();
				}
				else
				{
					loadProfile(profileKey);
					xpTracker.reset();
				}
				pushUi();
			}, false);
		}

		@Override
		public void refresh()
		{
			enqueue(profiles.current(), SettlementPlugin.this::pushUi, false);
		}
	}
}

package com.osrssettlement.engine;

import com.osrssettlement.model.BossTier;
import com.osrssettlement.model.Resource;
import java.util.Map;

/**
 * Every tuning number of the settlement economy. SettlementSimulationTest checks progression
 * against the configured first-Wonder target and acceptance factors.
 */
public final class Balance
{
	public static final int MAX_BUILDING_LEVEL = 10;
	public static final double COST_SCALE = 1;
	public static final double COST_GROWTH = 1.55;
	public static final int TOWN_HALL_UPGRADE_BUILDINGS = 3;
	public static final int WONDER_MIN_BUILDING_LEVEL = 10;
	public static final int WONDER_REQUIRED_BUILDING_COUNT = 20;
	public static final int FIRST_WONDER_TARGET_HOURS = 100;
	public static final double FIRST_WONDER_MAX_TARGET_FACTOR = 2;

	public static final double GATHER_BONUS_PER_LEVEL = 0.2;
	public static final double PROCESS_BONUS_PER_LEVEL = 0.1;
	public static final double TOWN_HALL_GLOBAL_BONUS = 0.02;
	public static final double WONDER_GLOBAL_BONUS = 0.1;
	public static final double ALTAR_GLOBAL_BONUS = 0.03;
	public static final double TROPHY_BONUS_PER_LEVEL = 0.15;
	public static final double TREASURY_BONUS_PER_LEVEL = 0.15;
	public static final double MUSEUM_BOUNTY_BONUS_PER_LEVEL = 0.10;
	public static final double LIBRARY_BOOST_DURATION_PER_LEVEL = 0.20;
	public static final double PYRAMID_EVENT_BONUS_PER_LEVEL = 0.10;
	public static final double TOWER_OF_VOICES_GLOBAL_BONUS = 0.05;

	public static final double PROCESS_INPUT_PER_UNIT = 0.5;

	public static final int GEM_MIN_BUILDING_LEVEL = 3;
	public static final double QUARRY_GEM_RATE = 0.05;
	public static final double THIEVES_GUILD_GEM_RATE = 0.1;
	public static final int KELDAGRIM_CONSORTIUM_INPUT_AMOUNT = 500;
	public static final int KELDAGRIM_CONSORTIUM_PROCESSED_INPUT_AMOUNT = 300;
	public static final int KELDAGRIM_CONSORTIUM_OUTPUT_AMOUNT = 100;
	public static final double KELDAGRIM_CONSORTIUM_OUTPUT_BONUS_PER_LEVEL = 0.1;
	public static final Map<BossTier, Map<Resource, Double>> BOSS_PART_DROP_CHANCES = Map.of(
		BossTier.TIER_1, Map.of(Resource.MONSTER_PARTS, 0.20, Resource.RARE_MONSTER_PARTS, 0.05, Resource.EPIC_MONSTER_PARTS, 0.01),
		BossTier.TIER_2, Map.of(Resource.MONSTER_PARTS, 0.35, Resource.RARE_MONSTER_PARTS, 0.1, Resource.EPIC_MONSTER_PARTS, 0.02),
		BossTier.TIER_3, Map.of(Resource.MONSTER_PARTS, 0.50, Resource.RARE_MONSTER_PARTS, 0.2, Resource.EPIC_MONSTER_PARTS, 0.05));
	public static final Map<BossTier, Integer> BOSS_PARTS_PER_DROP = Map.of(
		BossTier.TIER_1, 100,
		BossTier.TIER_2, 200,
		BossTier.TIER_3, 400);
	public static final int RAID_ARTIFACTS_TIER_2 = 1;
	public static final int RAID_ARTIFACTS_TIER_3 = 2;

	public static final int BOUNTY_SLOTS = 3;
	public static final int BOUNTY_SUPPLY_WEIGHT = 4;
	public static final int BOUNTY_BOOST_WEIGHT = 3;
	public static final int BOUNTY_PARTS_WEIGHT = 2;
	public static final double BOUNTY_COMMON_WEIGHT = 0.70;
	public static final double BOUNTY_RARE_WEIGHT = 0.20;
	public static final double BOUNTY_EPIC_WEIGHT = 0.05;
	public static final double BOUNTY_RARE_DEMAND_SCALE = 1.5;
	public static final double BOUNTY_EPIC_DEMAND_SCALE = 2.5;
	public static final double BOUNTY_RARE_YIELD_SCALE = 2.0;
	public static final double BOUNTY_EPIC_YIELD_SCALE = 4.0;
	// 3 hours of logged-in play; keeps a board of unreachable tasks from locking progress forever
	public static final int BOUNTY_EXPIRY_TICKS = 18_000;
	public static final double BOUNTY_SCALE_PER_TOWN_HALL = 0.3;
	public static final int BOUNTY_RARE_PARTS_TOWN_HALL = 3;
	public static final int BOUNTY_EPIC_PARTS_TOWN_HALL = 5;
	public static final int BOUNTY_ARTIFACT_TOWN_HALL = 6;
	// monster part rewards roll between a tier 1 and a tier 3 boss kill's expected parts
	public static final Map<Resource, Integer> BOUNTY_PARTS_MIN = Map.of(
		Resource.MONSTER_PARTS, 20, Resource.RARE_MONSTER_PARTS, 5, Resource.EPIC_MONSTER_PARTS, 1);
	public static final Map<Resource, Integer> BOUNTY_PARTS_MAX = Map.of(
		Resource.MONSTER_PARTS, 200, Resource.RARE_MONSTER_PARTS, 100, Resource.EPIC_MONSTER_PARTS, 40);
	public static final double BOUNTY_ARTIFACT_CHANCE = 0.02;
	public static final double CLUE_PART_CHANCE = 0.10;
	public static final int BOUNTY_SKILL_XP = 10_000;
	public static final int BOUNTY_GATHERING_XP = 15_000;
	public static final int BOUNTY_PROCESSING_XP = 15_000;
	public static final int BOUNTY_COMBAT_XP = 10_000;
	public static final int BOUNTY_SLAYER_DROPS = 200;
	public static final int BOUNTY_DELIVER = 150;
	public static final int BOUNTY_REWARD_VALUE = 400;
	public static final int BOUNTY_DELIVERY_REWARD_VALUE = 600;
	// lets accounts that never do Slayer still raise the Slayer Tower
	public static final double BOUNTY_MONSTER_PARTS_CHANCE = 0.1;
	public static final double BOOST_MULTIPLIER = 2.0;
	public static final int BOOST_TICKS = 3000;

	// 2 hours of logged-in play, and a new one every hour, so two usually overlap
	public static final int EVENT_DURATION_TICKS = 12_000;
	public static final int EVENT_INTERVAL_TICKS = 6_000;
	public static final double EVENT_BUFF_CHANCE = 0.7;

	public static final int LOG_SIZE = 50;

	public static final Map<Resource, Integer> STARTER_KIT = Map.of(
		Resource.LOGS, 100,
		Resource.STONE, 60,
		Resource.ORE, 40
	);

	private Balance()
	{
	}
}

package com.osrssettlement.engine;

import com.osrssettlement.model.Bounty;
import com.osrssettlement.model.BountyReward;
import com.osrssettlement.model.BountyRarity;
import com.osrssettlement.model.BountyType;
import com.osrssettlement.model.Building;
import com.osrssettlement.model.Resource;
import com.osrssettlement.model.ResourceCategory;
import com.osrssettlement.model.RewardType;
import com.osrssettlement.model.SettlementState;
import com.osrssettlement.model.SkillKind;
import com.osrssettlement.model.SkillRule;
import com.osrssettlement.model.SkillRules;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import net.runelite.api.Skill;

/**
 * Generates bounties for empty board slots. Blueprints that became available always take the
 * next free slot; everything else is drawn from a generic pool any account can work towards.
 */
public class BountyBoard
{
	private static final Map<BountyType, Integer> OBJECTIVE_WEIGHTS = Map.of(
		BountyType.SKILL_XP, 4,
		BountyType.KIND_XP, 3,
		BountyType.SLAYER_DROPS, 2,
		BountyType.BOSS_KILLS, 1,
		BountyType.CLUES, 1,
		BountyType.DELIVER, 2
	);
	private static final SkillKind[] XP_KINDS = {SkillKind.GATHERING, SkillKind.PROCESSING, SkillKind.COMBAT};

	private final Random random;

	public BountyBoard(Random random)
	{
		this.random = random;
	}

	public void fill(SettlementState state)
	{
		while (state.getBounties().size() < Balance.BOUNTY_SLOTS)
		{
			state.getBounties().add(generate(state));
		}
	}

	Bounty generate(SettlementState state)
	{
		int townHall = Math.max(1, state.getLevel(Building.TOWN_HALL));
		double scale = 1 + Balance.BOUNTY_SCALE_PER_TOWN_HALL * (townHall - 1);

		Building blueprint = nextBlueprint(state, random);
		BountyRarity rarity = blueprint == null ? randomRarity() : BountyRarity.COMMON;
		Bounty bounty = randomObjective(state, townHall, scale);
		bounty.setRarity(rarity);
		bounty.setId(state.getNextBountyId());
		bounty.setExpiresAtPlaytime(state.getPlaytimeTicks() + Balance.BOUNTY_EXPIRY_TICKS);
		state.setNextBountyId(state.getNextBountyId() + 1);

		bounty.setReward(blueprint != null ? BountyReward.blueprint(blueprint) : randomReward(state, bounty, townHall, scale));
		scaleForRarity(bounty);
		return bounty;
	}

	private BountyRarity randomRarity()
	{
		double totalWeight = Balance.BOUNTY_COMMON_WEIGHT + Balance.BOUNTY_RARE_WEIGHT + Balance.BOUNTY_EPIC_WEIGHT;
		double roll = random.nextDouble() * totalWeight;
		if (roll < Balance.BOUNTY_COMMON_WEIGHT)
		{
			return BountyRarity.COMMON;
		}
		if (roll < Balance.BOUNTY_COMMON_WEIGHT + Balance.BOUNTY_RARE_WEIGHT)
		{
			return BountyRarity.RARE;
		}
		return BountyRarity.EPIC;
	}

	static void scaleForRarity(Bounty bounty)
	{
		if (bounty.getRarity() == null || bounty.getRarity() == BountyRarity.COMMON)
		{
			return;
		}

		double demandScale;
		double yieldScale;
		if (bounty.getRarity() == BountyRarity.RARE)
		{
			demandScale = Balance.BOUNTY_RARE_DEMAND_SCALE;
			yieldScale = Balance.BOUNTY_RARE_YIELD_SCALE;
		}
		else
		{
			demandScale = Balance.BOUNTY_EPIC_DEMAND_SCALE;
			yieldScale = Balance.BOUNTY_EPIC_YIELD_SCALE;
		}

		bounty.setTarget(roundNice(bounty.getTarget() * demandScale));
		BountyReward reward = bounty.getReward();
		if (reward.getType() == RewardType.RESOURCES)
		{
			reward.getResources().replaceAll((resource, amount) -> (int) Math.min(Integer.MAX_VALUE,
				roundNice(amount * yieldScale)));
		}
		else if (reward.getType() == RewardType.BOOST)
		{
			reward.setBoostTicks((int) Math.min(Integer.MAX_VALUE,
				Math.round(reward.getBoostTicks() * yieldScale)));
		}
	}

	static Building nextBlueprint(SettlementState state, Random random)
	{
		if (state.getBounties().stream().anyMatch(Bounty::isBlueprint))
		{
			return null;
		}

		List<Building> eligible = new ArrayList<>();
		for (Building building : Building.values())
		{
			if (BuildingService.isBlueprintAvailable(state, building))
			{
				eligible.add(building);
			}
		}
		return eligible.isEmpty() ? null : eligible.get(random.nextInt(eligible.size()));
	}

	private Bounty randomObjective(SettlementState state, int townHall, double scale)
	{
		Set<BountyType> taken = EnumSet.noneOf(BountyType.class);
		state.getBounties().forEach(b -> taken.add(b.getType()));

		Map<BountyType, Integer> weights = new EnumMap<>(OBJECTIVE_WEIGHTS);
		if (!weights.keySet().stream().allMatch(taken::contains))
		{
			weights.keySet().removeAll(taken);
		}

		Bounty bounty = new Bounty();
		BountyType type = pickWeighted(weights);
		bounty.setType(type);

		switch (type)
		{
			case SKILL_XP:
				bounty.setSkill(pick(ruledSkills()));
				bounty.setTarget(roundNice(Balance.BOUNTY_SKILL_XP * scale));
				break;
			case KIND_XP:
				SkillKind kind = XP_KINDS[random.nextInt(XP_KINDS.length)];
				bounty.setKind(kind);
				bounty.setTarget(roundNice(kindTarget(kind) * scale));
				break;
			case SLAYER_DROPS:
				bounty.setTarget(roundNice(Balance.BOUNTY_SLAYER_DROPS * scale));
				break;
			case BOSS_KILLS:
				bounty.setTarget(1 + townHall / 3);
				break;
			case CLUES:
				bounty.setTarget(1 + townHall / 4);
				break;
			case DELIVER:
				bounty.setResource(pick(commonResources()));
				bounty.setTarget(roundNice(Balance.BOUNTY_DELIVER * scale));
				break;
			default:
				throw new IllegalStateException("Unhandled bounty type " + type);
		}
		return bounty;
	}

	private BountyReward randomReward(SettlementState state, Bounty bounty, int townHall, double scale)
	{
		int roll = random.nextInt(Balance.BOUNTY_SUPPLY_WEIGHT + Balance.BOUNTY_BOOST_WEIGHT + Balance.BOUNTY_PARTS_WEIGHT);
		if (roll < Balance.BOUNTY_SUPPLY_WEIGHT)
		{
			int budget = bounty.getType() == BountyType.DELIVER
				? Balance.BOUNTY_DELIVERY_REWARD_VALUE : Balance.BOUNTY_REWARD_VALUE;
			double value = budget * scale * YieldCalculator.museumMultiplier(state);
			return resourceReward(bounty.getResource(), value);
		}
		if (roll < Balance.BOUNTY_SUPPLY_WEIGHT + Balance.BOUNTY_BOOST_WEIGHT)
		{
			return BountyReward.boost(pick(boostableResources()), Balance.BOOST_MULTIPLIER, Balance.BOOST_TICKS);
		}
		return monsterPartsReward(townHall);
	}

	private BountyReward resourceReward(Resource exclude, double value)
	{
		List<Resource> pool = commonResources();
		pool.remove(exclude);

		int count = 2 + random.nextInt(2);
		int amount = (int) roundNice(value / count);
		Map<Resource, Integer> resources = new EnumMap<>(Resource.class);
		if (random.nextDouble() < Balance.BOUNTY_MONSTER_PARTS_CHANCE)
		{
			resources.put(Resource.MONSTER_PARTS, amount);
		}
		while (resources.size() < count)
		{
			Resource resource = pool.remove(random.nextInt(pool.size()));
			resources.put(resource, amount);
		}
		return BountyReward.resources(resources);
	}

	private BountyReward monsterPartsReward(int townHall)
	{
		double size = random.nextDouble();
		Map<Resource, Integer> resources = new EnumMap<>(Resource.class);
		resources.put(Resource.MONSTER_PARTS, bountyParts(Resource.MONSTER_PARTS, size));
		if (townHall >= Balance.BOUNTY_RARE_PARTS_TOWN_HALL)
		{
			resources.put(Resource.RARE_MONSTER_PARTS, bountyParts(Resource.RARE_MONSTER_PARTS, size));
		}
		if (townHall >= Balance.BOUNTY_EPIC_PARTS_TOWN_HALL)
		{
			resources.put(Resource.EPIC_MONSTER_PARTS, bountyParts(Resource.EPIC_MONSTER_PARTS, size));
		}
		if (townHall >= Balance.BOUNTY_ARTIFACT_TOWN_HALL && random.nextDouble() < Balance.BOUNTY_ARTIFACT_CHANCE)
		{
			resources.put(Resource.ARTIFACT, 1);
		}
		return BountyReward.resources(resources);
	}

	private static int bountyParts(Resource resource, double size)
	{
		int min = Balance.BOUNTY_PARTS_MIN.get(resource);
		int max = Balance.BOUNTY_PARTS_MAX.get(resource);
		return (int) roundNice(min + (max - min) * size);
	}

	private static int kindTarget(SkillKind kind)
	{
		switch (kind)
		{
			case GATHERING:
				return Balance.BOUNTY_GATHERING_XP;
			case PROCESSING:
				return Balance.BOUNTY_PROCESSING_XP;
			default:
				return Balance.BOUNTY_COMBAT_XP;
		}
	}

	private static List<Skill> ruledSkills()
	{
		List<Skill> skills = new ArrayList<>();
		for (Skill skill : Skill.values())
		{
			if (SkillRules.get(skill) != null)
			{
				skills.add(skill);
			}
		}
		return skills;
	}

	private static List<Resource> commonResources()
	{
		List<Resource> resources = new ArrayList<>();
		for (Resource resource : Resource.values())
		{
			if (resource.getCategory() == ResourceCategory.RAW || resource.getCategory() == ResourceCategory.REFINED)
			{
				resources.add(resource);
			}
		}
		return resources;
	}

	private static List<Resource> boostableResources()
	{
		Set<Resource> resources = EnumSet.noneOf(Resource.class);
		for (SkillRule rule : SkillRules.all())
		{
			resources.addAll(rule.getOutputs().keySet());
		}
		return new ArrayList<>(resources);
	}

	private <T> T pick(List<T> options)
	{
		return options.get(random.nextInt(options.size()));
	}

	private BountyType pickWeighted(Map<BountyType, Integer> weights)
	{
		int total = weights.values().stream().mapToInt(Integer::intValue).sum();
		int roll = random.nextInt(total);
		for (Map.Entry<BountyType, Integer> entry : weights.entrySet())
		{
			roll -= entry.getValue();
			if (roll < 0)
			{
				return entry.getKey();
			}
		}
		throw new IllegalStateException("Weights exhausted");
	}

	/**
	 * Rounds to two significant digits so targets read nicely (e.g. 13,500 -> 14,000).
	 */
	static long roundNice(double value)
	{
		if (value < 10)
		{
			return Math.max(1, Math.round(value));
		}
		double step = Math.pow(10, Math.floor(Math.log10(value)) - 1);
		return (long) (Math.round(value / step) * step);
	}
}

package com.osrssettlement.engine;

import com.osrssettlement.model.Building;
import com.osrssettlement.model.BuildingType;
import com.osrssettlement.model.Resource;
import com.osrssettlement.model.SettlementState;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

public final class BuildingService
{
	private BuildingService()
	{
	}

	/**
	 * @param level the level being built, starting at 1
	 */
	public static Map<Resource, Integer> cost(Building building, int level)
	{
		Map<Resource, Integer> cost = new EnumMap<>(Resource.class);
		building.getBaseCost().forEach((resource, base) ->
		{
			double amount = base * Balance.COST_SCALE * Math.pow(Balance.COST_GROWTH, level - 1);
			cost.put(resource, (int) Math.ceil(amount));
		});
		return Collections.unmodifiableMap(cost);
	}

	public static Map<Resource, Integer> nextCost(SettlementState state, Building building)
	{
		return cost(building, state.getLevel(building) + 1);
	}

	public static int maxLevel(Building building)
	{
		return Balance.MAX_BUILDING_LEVEL;
	}

	public static boolean hasTownHallFor(SettlementState state, Building building)
	{
		return state.getLevel(Building.TOWN_HALL) >= building.getTier().getRequiredTownHall();
	}

	/**
	 * A blueprint can be offered on the bounty board once the Town Hall is high enough and it is not owned yet.
	 */
	public static boolean isBlueprintAvailable(SettlementState state, Building building)
	{
		return ExpeditionCatalog.sourceOf(building) == null
			&& building.getTier().isBlueprintRequired()
			&& !state.getBlueprints().contains(building)
			&& hasTownHallFor(state, building);
	}

	/**
	 * Every non-resource requirement for the next level, in the order they are checked.
	 */
	public static List<Requirement> requirements(SettlementState state, Building building)
	{
		List<Requirement> requirements = new ArrayList<>();
		int level = state.getLevel(building);
		if (level >= maxLevel(building))
		{
			return requirements;
		}

		int townHall = state.getLevel(Building.TOWN_HALL);
		if (building != Building.TOWN_HALL && !building.isWonder())
		{
			int requiredTownHall = building.getTier().getRequiredTownHall();
			if (!building.isWonder())
			{
				requiredTownHall = Math.max(requiredTownHall, level + 1);
			}
			requirements.add(new Requirement(UpgradeCheck.Status.NEEDS_TOWN_HALL,
				"Town Hall level " + requiredTownHall, townHall >= requiredTownHall));
		}

		boolean ownsBlueprint = state.getBlueprints().contains(building);
		if (building.getTier().isBlueprintRequired() && (level == 0 || !ownsBlueprint))
		{
			ExpeditionCatalog.Definition expedition = ExpeditionCatalog.sourceOf(building);
			String source = expedition != null ? "expedition" : "bounty board";
			requirements.add(new Requirement(UpgradeCheck.Status.NEEDS_BLUEPRINT, "Blueprint (" + source + ")", ownsBlueprint));
		}

		if (building == Building.TOWN_HALL)
		{
			int required = Balance.TOWN_HALL_UPGRADE_BUILDINGS + level - 1;
			int current = countAtLevel(state, level);
			requirements.add(new Requirement(UpgradeCheck.Status.NEEDS_BUILDINGS,
				"Buildings at level " + level + " (" + current + "/" + required + ")",
				current >= required));
		}
		else if (building.isWonder() && level == 0)
		{
			int requiredLevel = Balance.WONDER_MIN_BUILDING_LEVEL;
			int current = countWonderEligibleBuildingsAtLevel(state, requiredLevel);
			int required = Balance.WONDER_REQUIRED_BUILDING_COUNT;
			requirements.add(new Requirement(UpgradeCheck.Status.NEEDS_BUILDINGS,
				"Buildings at level " + requiredLevel + " (" + current + "/" + required + ")",
				current >= required));
		}
		return requirements;
	}

	public static UpgradeCheck check(SettlementState state, Building building)
	{
		int level = state.getLevel(building);
		if (level >= maxLevel(building))
		{
			return UpgradeCheck.fail(UpgradeCheck.Status.MAX_LEVEL, "Maximum level reached");
		}

		for (Requirement requirement : requirements(state, building))
		{
			if (!requirement.isMet())
			{
				return UpgradeCheck.fail(requirement.getStatus(), "Requires: " + requirement.getDescription());
			}
		}

		if (!canAfford(state, cost(building, level + 1)))
		{
			return UpgradeCheck.fail(UpgradeCheck.Status.NEEDS_RESOURCES, "Not enough resources");
		}

		return UpgradeCheck.ok();
	}

	/**
	 * Pays for and applies the next level if allowed.
	 */
	static UpgradeCheck upgrade(SettlementState state, Building building)
	{
		UpgradeCheck check = check(state, building);
		if (!check.isOk())
		{
			return check;
		}

		int next = state.getLevel(building) + 1;
		cost(building, next).forEach((resource, amount) -> state.addStock(resource, -amount));
		state.setLevel(building, next);
		return check;
	}

	public static boolean canAfford(SettlementState state, Map<Resource, Integer> cost)
	{
		for (Map.Entry<Resource, Integer> entry : cost.entrySet())
		{
			if (state.getStock(entry.getKey()) < entry.getValue())
			{
				return false;
			}
		}
		return true;
	}

	private static int countAtLevel(SettlementState state, int level)
	{
		int count = 0;
		for (Building building : Building.values())
		{
			if (building != Building.TOWN_HALL && !building.isWonder() && state.getLevel(building) >= level)
			{
				count++;
			}
		}
		return count;
	}

	private static int countWonderEligibleBuildingsAtLevel(SettlementState state, int level)
	{
		int count = 0;
		for (Building building : Building.values())
		{
			if ((building.getType() == BuildingType.STANDARD || building.getType() == BuildingType.SPECIAL)
				&& state.getLevel(building) >= level)
			{
				count++;
			}
		}
		return count;
	}
}

package com.osrssettlement.engine;

import com.osrssettlement.model.ActiveEvent;
import com.osrssettlement.model.SettlementEvent;
import com.osrssettlement.model.SettlementState;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Starts a new event every hour of playtime; each lasts two hours, so after the first hour two overlap.
 */
public class EventScheduler
{
	private final Random random;

	public EventScheduler(Random random)
	{
		this.random = random;
	}

	public void tick(SettlementState state)
	{
		long now = state.getPlaytimeTicks();
		state.getEvents().removeIf(active -> active.getEndsAtPlaytime() <= now);
		if (state.getEvents().isEmpty() || now >= state.getNextEventAtPlaytime())
		{
			start(state);
		}
	}

	public void start(SettlementState state)
	{
		boolean buff = random.nextDouble() < Balance.EVENT_BUFF_CHANCE;
		List<SettlementEvent> pool = new ArrayList<>();
		for (SettlementEvent event : SettlementEvent.values())
		{
			if (event.isBuff() == buff)
			{
				pool.add(event);
			}
		}

		SettlementEvent next = pool.get(random.nextInt(pool.size()));
		long now = state.getPlaytimeTicks();
		state.getEvents().add(new ActiveEvent(next, now + Balance.EVENT_DURATION_TICKS));
		state.setNextEventAtPlaytime(now + Balance.EVENT_INTERVAL_TICKS);
		SettlementEngine.addLog(state, "Event: " + next.getDisplayName() + " - "
			+ next.describeEffect(YieldCalculator.effectiveEventMultiplier(state, next)));
	}
}

package com.osrssettlement.engine;

import com.osrssettlement.model.BossTier;
import com.osrssettlement.model.Building;
import com.osrssettlement.model.ExpeditionId;
import com.osrssettlement.model.ExpeditionProgress;
import com.osrssettlement.model.SettlementState;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;

/**
 * Five expeditions worked on one at a time: claiming one unlocks the next.
 */
public final class ExpeditionCatalog
{
	public enum ObjectiveType
	{
		SKILL_XP,
		MONSTER_PARTS,
		RARE_MONSTER_PARTS,
		EPIC_MONSTER_PARTS,
		CLUES,
		BOSS_KILLS,
		RAIDS
	}

	public static final class Objective
	{
		private final String id;
		private final String displayName;
		private final long target;
		private final ObjectiveType type;
		private final Skill skill;
		private final BossTier minTier;
		private final String encounterName;

		private Objective(String id, String displayName, long target, ObjectiveType type, Skill skill, BossTier minTier,
			String encounterName)
		{
			this.id = id;
			this.displayName = displayName;
			this.target = target;
			this.type = type;
			this.skill = skill;
			this.minTier = minTier;
			this.encounterName = encounterName;
		}

		static Objective xp(Skill skill, long target)
		{
			return new Objective(skill.name().toLowerCase(Locale.ROOT) + "Xp", "Gain " + skill.getName() + " XP", target,
				ObjectiveType.SKILL_XP, skill, null, null);
		}

		static Objective monsterParts(long target)
		{
			return new Objective("monsterParts", "Gather Basic Monster Parts", target, ObjectiveType.MONSTER_PARTS,
				null, null, null);
		}

		static Objective rareMonsterParts(long target)
		{
			return new Objective("rareMonsterParts", "Gather Rare Monster Parts", target,
				ObjectiveType.RARE_MONSTER_PARTS,
				null, null, null);
		}

		static Objective epicMonsterParts(long target)
		{
			return new Objective("epicMonsterParts", "Gather Epic Monster Parts", target,
				ObjectiveType.EPIC_MONSTER_PARTS,
				null, null, null);
		}

		static Objective clues(long target)
		{
			return new Objective("clues", "Complete clue scrolls", target, ObjectiveType.CLUES, null, null, null);
		}

		static Objective bosses(BossTier minTier, long target)
		{
			String tiers = minTier == BossTier.TIER_3 ? minTier.getDisplayName() : minTier.getDisplayName() + "+";
			return new Objective("bosses" + (minTier.ordinal() + 1), "Defeat " + tiers + " bosses", target,
				ObjectiveType.BOSS_KILLS, null, minTier, null);
		}

		static Objective raids(long target)
		{
			return new Objective("raids", "Complete raids", target, ObjectiveType.RAIDS, null, null, null);
		}

		static Objective boss(String id, String bossName, long target)
		{
			return new Objective(id, "Defeat " + bossName, target, ObjectiveType.BOSS_KILLS, null, null, bossName);
		}

		static Objective raid(String id, String raidName, long target)
		{
			return new Objective(id, "Complete " + raidName, target, ObjectiveType.RAIDS, null, null, raidName);
		}

		public String getId()
		{
			return id;
		}

		public String getDisplayName()
		{
			return displayName;
		}

		public long getTarget()
		{
			return target;
		}

		boolean matches(ObjectiveType type, Skill skill, BossTier tier, String eventName)
		{
			if (this.type != type || (encounterName != null && !matchesEncounter(eventName, encounterName)))
			{
				return false;
			}
			switch (type)
			{
				case SKILL_XP:
					return this.skill == skill;
				case BOSS_KILLS:
					return encounterName != null || tier != null && tier.ordinal() >= minTier.ordinal();
				default:
					return true;
			}
		}

		private static boolean matchesEncounter(String eventName, String encounterName)
		{
			if (eventName == null)
			{
				return false;
			}

			String actual = normalizeEncounter(eventName);
			String expected = normalizeEncounter(encounterName);
			return actual.equals(expected) || actual.startsWith(expected + ":") || actual.startsWith(expected + " ");
		}

		private static String normalizeEncounter(String name)
		{
			String normalized = name.toLowerCase(Locale.ROOT).trim();
			return normalized.startsWith("the ") ? normalized.substring(4) : normalized;
		}
	}

	public static final class Definition
	{
		private final ExpeditionId id;
		private final String displayName;
		private final int iconItemId;
		private final ExpeditionId prerequisite;
		private final Building rewardBlueprint;
		private final List<Objective> objectives;

		private Definition(ExpeditionId id, String displayName, int iconItemId, ExpeditionId prerequisite,
			Building rewardBlueprint, List<Objective> objectives)
		{
			this.id = id;
			this.displayName = displayName;
			this.iconItemId = iconItemId;
			this.prerequisite = prerequisite;
			this.rewardBlueprint = rewardBlueprint;
			this.objectives = Collections.unmodifiableList(objectives);
		}

		public ExpeditionId getId()
		{
			return id;
		}

		public String getDisplayName()
		{
			return displayName;
		}

		public int getIconItemId()
		{
			return iconItemId;
		}

		public Building getRewardBlueprint()
		{
			return rewardBlueprint;
		}

		public List<Objective> getObjectives()
		{
			return objectives;
		}
	}

