	SARADOMINS_BLESSING("Saradomin's blessing", "Saradomin's favor strengthens the Temple's blessings.", EventEffect.PROCESSING, Skill.PRAYER, 3),
	RESTLESS_GHOST("Restless ghost", "A restless ghost disturbs the Temple's blessings.", EventEffect.PROCESSING, Skill.PRAYER, 0.5),

	VARROCK_CARPENTERS("Varrock carpenters", "Carpenters from Varrock lend a hand at the Sawmill.", EventEffect.PROCESSING, Skill.CONSTRUCTION, 3),
	MATERIALS_SHORTAGE("Materials shortage", "A shortage of nails and planks stalls construction.", EventEffect.PROCESSING, Skill.CONSTRUCTION, 0.5),

	FEELING_LUCKY("Feeling lucky", "You're feeling lucky!", EventEffect.CLUES, null, 3),
	BROKEN_MIRROR("Broken mirror", "You broke a mirror. Luckily the curse only lasts a while.", EventEffect.CLUES, null, 0.5),

	REDBERRY_PIE("Redberry pie", "You've eaten Thurgo's redberry pie and feel stronger than ever.", EventEffect.MONSTER_DROPS, null, 3),
	DODGY_KEBAB("Dodgy kebab", "That Pollnivneach kebab didn't sit well.", EventEffect.MONSTER_DROPS, null, 0.5),

	SETTLEMENT_FESTIVAL("Settlement festival", "Your settlers work with festive spirit.", EventEffect.GLOBAL, null, 1.5),
	HEATWAVE("Heatwave", "A heatwave slows everyone down.", EventEffect.GLOBAL, null, 0.75);

	private final String displayName;
	private final String flavour;
	private final EventEffect effect;
	/** Only set for GATHERING and PROCESSING events. */
	private final Skill skill;
	private final double multiplier;

	SettlementEvent(String displayName, String flavour, EventEffect effect, Skill skill, double multiplier)
	{
		this.displayName = displayName;
		this.flavour = flavour;
		this.effect = effect;
		this.skill = skill;
		this.multiplier = multiplier;
	}

	public boolean isBuff()
	{
		return multiplier > 1;
	}

	public String describeEffect(double effective)
	{
		double rounded = Math.round(effective * 100) / 100.0;
		String factor = "x" + (rounded == Math.rint(rounded) ? String.valueOf((long) rounded) : String.valueOf(rounded));
		switch (effect)
		{
			case GATHERING:
				return skill.getName() + " yield " + factor;
			case PROCESSING:
				return skill.getName() + " output " + factor;
			case CLUES:
				return "Clue rewards " + factor;
			case MONSTER_DROPS:
				return "Monster drops " + factor;
			case GLOBAL:
			default:
				return "All yields " + factor;
		}
	}
}

package com.osrssettlement.model;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Data;
import lombok.NoArgsConstructor;
import net.runelite.api.Skill;

/**
 * Everything persisted for one account's settlement. Stock is stored as doubles so that
 * fractional yields accumulate; the UI shows the floored value.
 */
@Data
@NoArgsConstructor
public class SettlementState
{
	public static final int SCHEMA_VERSION = 6;

	private int schemaVersion = SCHEMA_VERSION;
	private Map<Resource, Double> stock = new EnumMap<>(Resource.class);
	private Map<Building, Integer> levels = new EnumMap<>(Building.class);
	private Set<Building> blueprints = EnumSet.noneOf(Building.class);
	private Map<Skill, Double> labour = new EnumMap<>(Skill.class);
	private boolean labourPaused;
	private List<Boost> boosts = new ArrayList<>();
	private List<Bounty> bounties = new ArrayList<>();
	private Map<ExpeditionId, ExpeditionProgress> expeditions = new EnumMap<>(ExpeditionId.class);
	private List<LogEntry> log = new ArrayList<>();
	private long playtimeTicks;
	private int nextBountyId = 1;
	private int bountiesCompleted;
	private List<ActiveEvent> events = new ArrayList<>();
	private long nextEventAtPlaytime;

	public double getStock(Resource resource)
	{
		return stock.getOrDefault(resource, 0.0);
	}

	public void addStock(Resource resource, double amount)
	{
		stock.merge(resource, amount, Double::sum);
	}

	public int getLevel(Building building)
	{
		return levels.getOrDefault(building, 0);
	}

	public void setLevel(Building building, int level)
	{
		levels.put(building, level);
	}

	public double getLabour(Skill skill)
	{
		return labour.getOrDefault(skill, 0.0);
	}

	public ExpeditionProgress getExpeditionProgress(ExpeditionId id)
	{
		return expeditions.computeIfAbsent(id, ignored -> new ExpeditionProgress());
	}

}

package com.osrssettlement.model;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum SkillKind
{
	GATHERING("gathering"),
	PROCESSING("processing"),
	COMBAT("Hitpoints"),
	SLAYER("slayer");

	private final String displayName;
}

package com.osrssettlement.model;

import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import lombok.Getter;
import net.runelite.api.Skill;

/**
 * How XP in one skill feeds the settlement. Gathering skills produce their outputs directly;
 * processing skills convert their inputs (in priority order) into a single output.
 */
@Getter
public final class SkillRule
{
	private final Skill skill;
	private final SkillKind kind;
	private final Building building;
	private final Map<Resource, Double> outputs;
	private final List<Resource> inputs;

	private SkillRule(Skill skill, SkillKind kind, Building building, Map<Resource, Double> outputs, List<Resource> inputs)
	{
		this.skill = skill;
		this.kind = kind;
		this.building = building;
		this.outputs = Collections.unmodifiableMap(new EnumMap<>(outputs));
		this.inputs = List.copyOf(inputs);
	}

	static SkillRule produce(Skill skill, SkillKind kind, Building building, Map<Resource, Double> outputs)
	{
		return new SkillRule(skill, kind, building, outputs, List.of());
	}

	static SkillRule process(Skill skill, Building building, Resource output, Resource... inputs)
	{
		return new SkillRule(skill, SkillKind.PROCESSING, building, Map.of(output, 1.0), List.of(inputs));
	}

	/**
	 * The single output of a processing skill.
	 */
	public Resource getOutput()
	{
		return outputs.keySet().iterator().next();
	}

	public boolean isProcessing()
	{
		return kind == SkillKind.PROCESSING;
	}
}

package com.osrssettlement.model;

import static com.osrssettlement.model.Resource.*;
import java.util.Collection;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;

public final class SkillRules
{
	private static final Map<Skill, SkillRule> RULES = new EnumMap<>(Skill.class);

	static
	{
		gather(Skill.WOODCUTTING, Building.LUMBER_CAMP, Map.of(LOGS, 1.0));
		gather(Skill.MINING, Building.QUARRY, Map.of(ORE, 0.5, STONE, 0.5));
		gather(Skill.FISHING, Building.FISHING_DOCK, Map.of(FISH, 1.0));
		gather(Skill.HUNTER, Building.HUNTERS_LODGE, Map.of(HIDES, 1.0));
		gather(Skill.FARMING, Building.FARMSTEAD, Map.of(GRAIN, 0.5, HERBS, 0.5));
		gather(Skill.THIEVING, Building.THIEVES_GUILD, Map.of(COINS, 1.0));
		gather(Skill.AGILITY, Building.COURIER_POST, Map.of(MARKS, 1.0));
		gather(Skill.SAILING, Building.HARBOR, Map.of(CARGO, 1.0));

		add(SkillRule.produce(Skill.HITPOINTS, SkillKind.COMBAT, Building.BARRACKS, Map.of(BONES, 1.0)));
		add(SkillRule.produce(Skill.SLAYER, SkillKind.SLAYER, Building.SLAYER_TOWER, Map.of(MONSTER_PARTS, 1.0)));

		add(SkillRule.process(Skill.SMITHING, Building.FORGE, BARS, ORE));
		add(SkillRule.process(Skill.FIREMAKING, Building.FORGE, CHARCOAL, LOGS));
		add(SkillRule.process(Skill.CONSTRUCTION, Building.SAWMILL, PLANKS, LOGS));
		add(SkillRule.process(Skill.CRAFTING, Building.WORKSHOP, LEATHER, HIDES));
		add(SkillRule.process(Skill.FLETCHING, Building.WORKSHOP, ARROWS, LOGS));
		add(SkillRule.process(Skill.COOKING, Building.TAVERN, RATIONS, FISH, GRAIN));
		add(SkillRule.process(Skill.HERBLORE, Building.APOTHECARY, POTIONS, HERBS));
		add(SkillRule.process(Skill.RUNECRAFT, Building.WIZARD_TOWER, RUNES, STONE));
		add(SkillRule.process(Skill.MAGIC, Building.WIZARD_TOWER, ENCHANTMENTS, RUNES));
		add(SkillRule.process(Skill.PRAYER, Building.TEMPLE, BLESSINGS, BONES));
	}

	private SkillRules()
	{
	}

	private static void gather(Skill skill, Building building, Map<Resource, Double> outputs)
	{
		add(SkillRule.produce(skill, SkillKind.GATHERING, building, outputs));
	}

	private static void add(SkillRule rule)
	{
		RULES.put(rule.getSkill(), rule);
	}

	/**
	 * @return the rule for a skill, or null if the skill does not feed the settlement
	 */
	public static SkillRule get(Skill skill)
	{
		return RULES.get(skill);
	}

	public static Collection<SkillRule> all()
	{
		return Collections.unmodifiableCollection(RULES.values());
	}
}

package com.osrssettlement.persistence;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonPrimitive;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.osrssettlement.engine.Balance;
import com.osrssettlement.model.Bounty;
import com.osrssettlement.model.BountyType;
import com.osrssettlement.model.Building;
import com.osrssettlement.model.RewardType;
import com.osrssettlement.model.SettlementState;
import java.io.IOException;
import java.io.StringReader;
import java.math.BigDecimal;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

@Slf4j
@Singleton
public class SettlementStore
{
	public static final String CONFIG_GROUP = "osrs-settlement";
	static final String STATE_KEY = "state";
	static final String RESET_BACKUP_KEY = "state-before-reset";

	public enum Status
	{
		NEW, READY, UNSUPPORTED_VERSION, INVALID_DATA, STORAGE_ERROR
	}

	interface Configuration
	{
		String get(String profile, String key);
		void set(String profile, String key, String value);
	}

	@Getter
	public static final class Session
	{
		private final String profileKey;
		private final Status status;
		private final SettlementState state;
		private final String message;
		private String expectedJson;
		private String attemptedJson;
		private boolean writable;
		private String recoveryPrimary;
		private String recoveryBackup;
		private String recoveryLive;
		private String checkedBackup;
		private boolean checkedBackupValid;

		private Session(String profileKey, Status status, SettlementState state, String message, String json)
		{
			this.profileKey = profileKey;
			this.status = status;
			this.state = state;
			this.message = message;
			this.expectedJson = json;
			this.writable = status == Status.NEW || status == Status.READY;
		}
	}

	private final Configuration configuration;
	private final Gson gson;

	@Inject
	SettlementStore(ConfigManager configManager, Gson gson)
	{
		this(new Configuration()
		{
			@Override
			public String get(String profile, String key)
			{
				return configManager.getConfiguration(CONFIG_GROUP, profile, key);
			}

			@Override
			public void set(String profile, String key, String value)
			{
				configManager.setConfiguration(CONFIG_GROUP, profile, key, value);
			}
		}, gson);
	}

	SettlementStore(Configuration configuration, Gson gson)
	{
		this.configuration = configuration;
		this.gson = gson;
	}

	public synchronized Session load(String profileKey)
	{
		if (profileKey == null)
		{
			return new Session(null, Status.STORAGE_ERROR, null, "No account loaded.", null);
		}
		String json;
		try
		{
			json = configuration.get(profileKey, STATE_KEY);
			if (json == null)
			{
				return hasBackup(profileKey)
					? new Session(profileKey, Status.INVALID_DATA, null,
						"Saved progress is missing, but protected recovery data exists.", null)
					: new Session(profileKey, Status.NEW, null, null, null);
			}
		}
		catch (RuntimeException exception)
		{
			log.warn("Unable to read settlement configuration", exception);
			return new Session(profileKey, Status.STORAGE_ERROR, null,
				"Unable to read saved progress. No replacement settlement was created.", null);
		}
		try
		{
			return new Session(profileKey, Status.READY, fromJson(gson, json), null, json);
		}
		catch (UnsupportedVersionException exception)
		{
			return new Session(profileKey, Status.UNSUPPORTED_VERSION, null,
				"This settlement uses an unsupported data version. Its saved progress has been preserved.", json);
		}
		catch (RuntimeException exception)
		{
			log.warn("Unable to validate saved settlement", exception);
			return new Session(profileKey, Status.INVALID_DATA, null,
				"Saved progress could not be safely loaded. It has not been replaced or repaired.", json);
		}
	}

	public String snapshot(SettlementState state)
	{
		String json = gson.toJson(state);
		fromJson(gson, json);
		return json;
	}

	public synchronized void save(Session session, String json)
	{
		requireWritable(session);
		fromJson(gson, json);
		String current = configuration.get(session.profileKey, STATE_KEY);
		if (session.attemptedJson != null && Objects.equals(current, session.attemptedJson))
		{
			session.expectedJson = current;
		}
		if (!Objects.equals(current, session.expectedJson)
			|| current == null && hasBackup(session.profileKey))
		{
			session.writable = false;
			throw new IllegalStateException("Saved progress changed outside this session. No overwrite was attempted.");
		}
		try
		{
			session.attemptedJson = json;
			configuration.set(session.profileKey, STATE_KEY, json);
		}
		catch (RuntimeException exception)
		{
			try
			{
				if (Objects.equals(configuration.get(session.profileKey, STATE_KEY), json))
				{
					session.expectedJson = json;
				}
			}
			catch (RuntimeException readFailure)
			{
				exception.addSuppressed(readFailure);
			}
			throw exception;
		}
		if (!Objects.equals(configuration.get(session.profileKey, STATE_KEY), json))
		{
			session.writable = false;
			throw new IllegalStateException("Saved progress could not be confirmed. Further writes are blocked.");
		}
		session.expectedJson = json;
		session.attemptedJson = null;
	}

	public synchronized void reset(Session session, String previous, String replacement)
	{
		requireWritable(session);
		fromJson(gson, previous);
		fromJson(gson, replacement);
		if (session.expectedJson == null
			|| !Objects.equals(configuration.get(session.profileKey, STATE_KEY), session.expectedJson))
		{
			throw new IllegalStateException("Saved progress changed or has not been saved. Reset was cancelled.");
		}
		configuration.set(session.profileKey, RESET_BACKUP_KEY, previous);
		if (!previous.equals(configuration.get(session.profileKey, RESET_BACKUP_KEY)))
		{
			throw new IllegalStateException("The pre-reset backup could not be confirmed. Reset was cancelled.");
		}
		save(session, replacement);
	}

	public synchronized String restorableSnapshot(Session session)
	{
		if (session == null || !session.writable || session.expectedJson == null)
		{
			return null;
		}
		try
		{
			String json = configuration.get(session.profileKey, RESET_BACKUP_KEY);
			if (json == null)
			{
				return null;
			}
			if (!json.equals(session.checkedBackup))
			{
				session.checkedBackup = json;
				session.checkedBackupValid = false;
				fromJson(gson, json);
				session.checkedBackupValid = true;
			}
			return session.checkedBackupValid ? json : null;
		}
		catch (RuntimeException exception)
		{
			log.debug("Pre-reset snapshot is unavailable", exception);
			return null;
		}
	}

	public SettlementState restoreState(String json)
	{
		return fromJson(gson, json);
	}

	public synchronized void restore(Session session, String live, String backup)
	{
		requireWritable(session);
		fromJson(gson, live);
		fromJson(gson, backup);
		if (session.expectedJson == null
			|| !Objects.equals(configuration.get(session.profileKey, STATE_KEY), session.expectedJson)
			|| !Objects.equals(configuration.get(session.profileKey, RESET_BACKUP_KEY), backup))
		{
			throw new IllegalStateException("Saved progress changed. Restore was cancelled.");
		}
		session.recoveryPrimary = session.expectedJson;
		session.recoveryBackup = backup;
		session.recoveryLive = live;
		session.writable = false;
		try
		{
			writeVerified(session.profileKey, STATE_KEY, backup);
			writeVerified(session.profileKey, RESET_BACKUP_KEY, live);
			session.expectedJson = backup;
			session.attemptedJson = null;
			session.recoveryPrimary = null;
			session.recoveryBackup = null;
			session.recoveryLive = null;
			session.writable = true;
		}
		catch (RuntimeException exception)
		{
			try
			{
				recoverRestore(session);
			}
			catch (RuntimeException recoveryFailure)
			{
				exception.addSuppressed(recoveryFailure);
			}
			throw exception;
		}
	}

	public synchronized void recoverRestore(Session session)
	{
		if (session == null || session.recoveryPrimary == null)
		{
			return;
		}
		String primary = configuration.get(session.profileKey, STATE_KEY);
		String backup = configuration.get(session.profileKey, RESET_BACKUP_KEY);
		if (!(Objects.equals(primary, session.recoveryPrimary) || Objects.equals(primary, session.recoveryBackup))
			|| !(Objects.equals(backup, session.recoveryBackup) || Objects.equals(backup, session.recoveryLive)))
		{
			throw new IllegalStateException("Saved progress changed during restore recovery. No overwrite was attempted.");
		}
		writeVerified(session.profileKey, RESET_BACKUP_KEY, session.recoveryBackup);
		writeVerified(session.profileKey, STATE_KEY, session.recoveryPrimary);
		session.expectedJson = session.recoveryPrimary;
		session.attemptedJson = null;
		session.recoveryPrimary = null;
		session.recoveryBackup = null;
		session.recoveryLive = null;
		session.writable = true;
	}

	private void writeVerified(String profile, String key, String json)
	{
		try
		{
			configuration.set(profile, key, json);
		}
		catch (RuntimeException exception)
		{
			if (!Objects.equals(configuration.get(profile, key), json))
			{
				throw exception;
			}
		}
		if (!Objects.equals(configuration.get(profile, key), json))
		{
			throw new IllegalStateException("Settlement write could not be confirmed.");
		}
	}

	private boolean hasBackup(String profile)
	{
		return configuration.get(profile, RESET_BACKUP_KEY) != null;
	}

	private static void requireWritable(Session session)
	{
		if (session == null || session.profileKey == null || !session.writable)
		{
			throw new IllegalStateException("This settlement is protected from writes.");
		}
	}

	static SettlementState fromJson(Gson gson, String json)
	{
		JsonElement root;
		try (JsonReader reader = new JsonReader(new StringReader(json)))
		{
			root = readJson(reader, 0);
			valid(reader.peek() == JsonToken.END_DOCUMENT);
		}
		catch (IOException exception)
		{
			throw new JsonParseException("Invalid settlement JSON", exception);
		}
		if (!root.isJsonObject())
		{
			throw new JsonParseException("Expected a settlement object");
		}
		JsonElement version = root.getAsJsonObject().get("schemaVersion");
		if (version == null || !version.isJsonPrimitive() || !version.getAsJsonPrimitive().isNumber())
		{
			throw new JsonParseException("Missing schema version");
		}
		if (version.getAsBigDecimal().intValueExact() != SettlementState.SCHEMA_VERSION)
		{
			throw new UnsupportedVersionException();
		}
		SettlementState state = gson.fromJson(root, SettlementState.class);
		if (!preserves(root, gson.toJsonTree(state)))
		{
			throw new JsonParseException("Unknown or incompatible saved fields");
		}
		validate(state);
		return state;
	}

	private static JsonElement readJson(JsonReader reader, int depth) throws IOException
	{
		valid(depth <= 32);
		switch (reader.peek())
		{
			case BEGIN_OBJECT:
				JsonObject object = new JsonObject();
				reader.beginObject();
				while (reader.hasNext())
				{
					String name = reader.nextName();
					valid(!object.has(name));
					object.add(name, readJson(reader, depth + 1));
				}
				reader.endObject();
				return object;
			case BEGIN_ARRAY:
				JsonArray array = new JsonArray();
				reader.beginArray();
				while (reader.hasNext())
				{
					array.add(readJson(reader, depth + 1));
				}
				reader.endArray();
				return array;
			case STRING:
				return new JsonPrimitive(reader.nextString());
			case NUMBER:
				return new JsonPrimitive(new BigDecimal(reader.nextString()));
			case BOOLEAN:
				return new JsonPrimitive(reader.nextBoolean());
			case NULL:
				reader.nextNull();
				return com.google.gson.JsonNull.INSTANCE;
			default:
				throw new JsonParseException("Expected a JSON value");
		}
	}

	private static boolean preserves(JsonElement source, JsonElement result)
	{
		if (source.isJsonObject() && result != null && result.isJsonObject())
		{
			JsonObject target = result.getAsJsonObject();
			for (Map.Entry<String, JsonElement> entry : source.getAsJsonObject().entrySet())
			{
				if (!preserves(entry.getValue(), target.get(entry.getKey())))
				{
					return false;
				}
			}
			return true;
		}
		if (source.isJsonArray() && result != null && result.isJsonArray())
		{
			if (source.getAsJsonArray().size() != result.getAsJsonArray().size())
			{
				return false;
			}
			for (int index = 0; index < source.getAsJsonArray().size(); index++)
			{
				if (!preserves(source.getAsJsonArray().get(index), result.getAsJsonArray().get(index)))
				{
					return false;
				}
			}
			return true;
		}
		if (source.isJsonPrimitive() && source.getAsJsonPrimitive().isNumber()
			&& result != null && result.isJsonPrimitive() && result.getAsJsonPrimitive().isNumber())
		{
			return source.getAsBigDecimal().compareTo(result.getAsBigDecimal()) == 0;
		}
		return source.equals(result);
	}

	private static void validate(SettlementState state)
	{
		valid(state.getStock() != null && state.getLabour() != null && state.getLevels() != null
			&& state.getBlueprints() != null && state.getBounties() != null && state.getBoosts() != null
			&& state.getEvents() != null && state.getExpeditions() != null && state.getLog() != null);
		state.getStock().forEach((key, value) -> valid(key != null && nonnegative(value)));
		state.getLabour().forEach((key, value) -> valid(key != null && nonnegative(value)));
		state.getLevels().forEach((key, value) -> valid(key != null && value != null && value >= 0
			&& (key == Building.WONDER || value <= Balance.MAX_BUILDING_LEVEL
				&& value <= state.getLevel(Building.TOWN_HALL))));
		valid(state.getLevel(Building.TOWN_HALL) >= 1);
		valid(!state.getBlueprints().contains(null) && state.getPlaytimeTicks() >= 0
			&& state.getNextEventAtPlaytime() >= 0 && state.getNextBountyId() > 0 && state.getBountiesCompleted() >= 0);
		state.getBoosts().forEach(boost -> valid(boost != null && boost.getResource() != null
			&& Double.isFinite(boost.getMultiplier()) && boost.getMultiplier() >= 1 && boost.getRemainingTicks() > 0));
		state.getEvents().forEach(event -> valid(event != null && event.getEvent() != null && event.getEndsAtPlaytime() >= 0));
		state.getExpeditions().forEach((key, progress) ->
		{
			valid(key != null && progress != null && progress.getObjectives() != null);
			progress.getObjectives().forEach((objective, amount) -> valid(objective != null && nonnegative(amount)));
		});
		Set<Integer> ids = new HashSet<>();
		for (Bounty bounty : state.getBounties())
		{
			valid(bounty != null && bounty.getType() != null && bounty.getRarity() != null
				&& bounty.getId() > 0 && ids.add(bounty.getId()) && bounty.getId() < state.getNextBountyId()
				&& bounty.getTarget() > 0 && nonnegative(bounty.getProgress()) && bounty.getExpiresAtPlaytime() > 0
				&& bounty.getReward() != null && bounty.getReward().getType() != null);
			valid(bounty.getType() != BountyType.SKILL_XP || bounty.getSkill() != null);
			valid(bounty.getType() != BountyType.KIND_XP || bounty.getKind() != null);
			valid(bounty.getType() != BountyType.DELIVER || bounty.getResource() != null);
			valid(bounty.getReward().getResources() != null);
			bounty.getReward().getResources().forEach((key, amount) -> valid(key != null && amount != null && amount >= 0));
			valid(bounty.getReward().getType() != RewardType.BLUEPRINT || bounty.getReward().getBlueprint() != null);
			valid(bounty.getReward().getType() != RewardType.BOOST || bounty.getReward().getBoostResource() != null
				&& Double.isFinite(bounty.getReward().getBoostMultiplier()) && bounty.getReward().getBoostMultiplier() >= 1
				&& bounty.getReward().getBoostTicks() > 0);
		}
		state.getLog().forEach(entry -> valid(entry != null && entry.getMessage() != null && entry.getPlaytimeTicks() >= 0));
	}

	private static boolean nonnegative(Double value)
	{
		return value != null && Double.isFinite(value) && value >= 0;
	}

	private static void valid(boolean condition)
	{
		if (!condition)
		{
			throw new JsonParseException("Invalid settlement progress");
		}
	}

	private static final class UnsupportedVersionException extends JsonParseException
	{
		private UnsupportedVersionException()
		{
			super("Unsupported settlement schema");
		}
	}
}

package com.osrssettlement.tracking;

import com.osrssettlement.model.BossTier;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Allowlist of bosses whose kill count messages grant settlement rewards. Kill count messages also exist
 * for agility laps, Wintertodt, Tempoross, etc.; anything not listed here is ignored.
 */
public final class BossRegistry
{
	private static final Map<String, BossTier> TIERS = new HashMap<>();
	private static final Set<String> RAIDS = Set.of("chambers of xeric", "theatre of blood", "tombs of amascut");
	private static final List<String> NAMES_LONGEST_FIRST;

	static
	{
		register(BossTier.TIER_1,
			"giant mole", "obor", "bryophyta", "scurrius", "sarachnis", "barrows", "deranged archaeologist",
			"crazy archaeologist", "chaos fanatic", "chaos elemental", "king black dragon", "kalphite queen",
			"dagannoth prime", "dagannoth rex", "dagannoth supreme", "skotizo", "hespori", "zalcano", "kraken",
			"tempoross",
			"thermonuclear smoke devil", "amoxliatl", "lunar", "royal titans", "mimic", "scorpia", "artio",
			"calvar'ion", "spindel", "brutus", "wintertodt");
		register(BossTier.TIER_2,
			"zulrah", "vorkath", "commander zilyana", "general graardor", "kree'arra", "k'ril tsutsaroth",
			"cerberus", "abyssal sire", "alchemical hydra", "grotesque guardians", "gauntlet", "phantom muspah",
			"callisto", "venenatis", "vet'ion", "corporeal beast", "nightmare", "duke sucellus", "leviathan",
			"whisperer", "vardorvis", "hueycoatl", "tztok-jad", "araxxor", "doom of mokhaiotl",
			"shellbane gryphon", "maggot king", "mad angel");
		register(BossTier.TIER_3,
			"chambers of xeric", "theatre of blood", "tombs of amascut", "nex", "corrupted gauntlet",
			"phosani's nightmare", "tzkal-zuk", "sol heredit", "yama");

		List<String> names = new ArrayList<>(TIERS.keySet());
		names.sort(Comparator.comparingInt(String::length).reversed());
		NAMES_LONGEST_FIRST = List.copyOf(names);
	}

	private BossRegistry()
	{
	}

	private static void register(BossTier tier, String... names)
	{
		for (String name : names)
		{
			TIERS.put(name, tier);
		}
	}

	/**
	 * @param bossName the name as shown in a kill count message, e.g. "Theatre of Blood: Entry Mode"
	 * @return the reward tier, or null if this is not a rewarded boss
	 */
	public static BossTier tierOf(String bossName)
	{
		String name = bossName.toLowerCase(Locale.ROOT).trim();
		if (name.startsWith("the "))
		{
			name = name.substring(4);
		}
		name = name.replace("(echo)", "").trim();

		boolean awakened = name.contains("(awakened)");
		name = name.replace("(awakened)", "").trim();

		boolean entryMode = name.contains("entry mode") || name.contains("story mode");

		for (String known : NAMES_LONGEST_FIRST)
		{
			if (name.startsWith(known))
			{
				BossTier tier = TIERS.get(known);
				if (awakened)
				{
					return BossTier.TIER_3;
				}
				if (entryMode && tier == BossTier.TIER_3)
				{
					return BossTier.TIER_2;
				}
				return tier;
			}
		}
		return null;
	}

	public static boolean isRaid(String bossName)
	{
		String name = bossName.toLowerCase(Locale.ROOT).trim();
		if (name.startsWith("the "))
		{
			name = name.substring(4);
		}
		for (String raid : RAIDS)
		{
			if (name.startsWith(raid))
			{
				return true;
			}
		}
		return false;
	}
}

package com.osrssettlement.tracking;

import com.osrssettlement.model.ClueTier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/**
 * Recognises the game messages that reward the settlement: boss kill counts and clue completions.
 */
public final class ChatEventParser
{
	// Same pattern RuneLite's chat commands plugin uses to track kill counts
	private static final Pattern KILLCOUNT_PATTERN = Pattern.compile("Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? (?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?(?:<col=[0-9a-f]{6}>|@.+?@)(?<kc>[0-9,]+)</col>");
	private static final Pattern CLUE_PATTERN = Pattern.compile("You have completed [0-9,]+ ([a-z]+) Treasure Trails?");

	private ChatEventParser()
	{
	}

	/**
	 * @return the boss name of a kill count message, or null if the message is not one
	 */
	public static String parseKillCount(String message)
	{
		Matcher matcher = KILLCOUNT_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return null;
		}

		String pre = matcher.group("pre");
		String post = matcher.group("post");
		if ((pre == null || pre.isEmpty()) && (post == null || post.isEmpty()))
		{
			return null;
		}
		return Text.removeTags(matcher.group("boss")).trim();
	}

	/**
	 * @return the tier of a clue completion message, or null if the message is not one
	 */
	public static ClueTier parseClue(String message)
	{
		Matcher matcher = CLUE_PATTERN.matcher(Text.removeTags(message));
		if (!matcher.find())
		{
			return null;
		}
		return ClueTier.fromName(matcher.group(1));
	}
}

package com.osrssettlement.tracking;

import java.util.EnumMap;
import java.util.Map;
import java.util.function.ToIntFunction;
import net.runelite.api.Skill;

/**
 * Turns absolute skill XP into gained XP. The stat sync right after login or a world hop only
 * sets the baseline, so XP earned while the plugin was not running is never credited.
 */
public class XpTracker
{
	static final int LOGIN_SYNC_TICKS = 2;

	private final Map<Skill, Integer> baseline = new EnumMap<>(Skill.class);
	private int syncTicks;

	/**
	 * Forget the baseline and ignore stat updates for the next couple of ticks.
	 */
	public void reset()
	{
		baseline.clear();
		syncTicks = LOGIN_SYNC_TICKS;
	}

	/**
	 * @return true on the tick the login sync finishes and a baseline snapshot should be taken
	 */
	public boolean tick()
	{
		return syncTicks > 0 && --syncTicks == 0;
	}

	public void snapshot(ToIntFunction<Skill> currentXp)
	{
		syncTicks = 0;
		for (Skill skill : Skill.values())
		{
			baseline.put(skill, currentXp.applyAsInt(skill));
		}
	}

	/**
	 * @return the XP gained since the last update of this skill, or 0 while syncing or without a baseline
	 */
	public int onStatChanged(Skill skill, int xp)
	{
		if (syncTicks > 0)
		{
			return 0;
		}

		Integer previous = baseline.put(skill, xp);
		if (previous == null)
		{
			return 0;
		}
		return Math.max(0, xp - previous);
	}
}

package com.osrssettlement.ui;

import com.osrssettlement.engine.Balance;
