import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;

class ActivityTab extends JPanel
{
	private final List<BountyCard> cards = new ArrayList<>();
	private final JPanel boostPanel = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
	private final JLabel completedLabel = Ui.label("", FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR);
	private final JLabel rewardToast = Ui.label("", FontManager.getRunescapeBoldFont(), Ui.GOOD);
	private final List<EventBanner> eventBanners = new ArrayList<>();
	private final JPanel eventPanel = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
	private final JPanel eventBlock = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
	private final JLabel eventsTitle = Ui.sectionTitle("Events");
	private final ExpeditionPanel expeditionPanel;
	private Timer rewardTimer;

	ActivityTab(ItemManager itemManager, SettlementActions actions)
	{
		setLayout(new DynamicGridLayout(0, 1, 0, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		rewardToast.setHorizontalAlignment(SwingConstants.CENTER);
		rewardToast.setVisible(false);
		eventPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		eventBlock.setOpaque(false);
		eventBlock.add(eventPanel);
		boostPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		boostPanel.setBorder(new EmptyBorder(6, 6, 6, 6));
		boostPanel.add(Ui.label("Active boosts", FontManager.getRunescapeBoldFont(), Ui.GOOD));
		add(eventsTitle);
		add(eventBlock);
		add(rewardToast);

		add(Ui.sectionTitle("Bounties"));
		for (int i = 0; i < Balance.BOUNTY_SLOTS; i++)
		{
			BountyCard card = new BountyCard(actions);
			cards.add(card);
			add(card);
		}
		add(completedLabel);

		add(Ui.sectionTitle("Expeditions"));
		expeditionPanel = new ExpeditionPanel(itemManager, actions);
		add(expeditionPanel);
	}

	void showReward(String text)
	{
		if (rewardTimer != null)
		{
			rewardTimer.stop();
		}

		Color start = Ui.GOOD;
		Color end = ColorScheme.DARK_GRAY_COLOR;
		long startedAt = System.currentTimeMillis();
		rewardToast.setText(Ui.wrap(text));
		rewardToast.setForeground(start);
		rewardToast.setVisible(true);
		revalidate();

		rewardTimer = new Timer(35, event ->
		{
			double progress = Math.min(1, (System.currentTimeMillis() - startedAt) / 1100.0);
			int red = (int) (start.getRed() + (end.getRed() - start.getRed()) * progress);
			int green = (int) (start.getGreen() + (end.getGreen() - start.getGreen()) * progress);
			int blue = (int) (start.getBlue() + (end.getBlue() - start.getBlue()) * progress);
			rewardToast.setForeground(new Color(red, green, blue));
			if (progress >= 1)
			{
				rewardTimer.stop();
				rewardToast.setVisible(false);
				revalidate();
			}
		});
		rewardTimer.start();
	}

	void update(SettlementState state)
	{
		List<ActiveEvent> events = state.getEvents();
		while (eventBanners.size() < events.size())
		{
			EventBanner banner = new EventBanner();
			eventBanners.add(banner);
			eventPanel.add(banner);
		}
		while (eventBanners.size() > events.size())
		{
			eventPanel.remove(eventBanners.remove(eventBanners.size() - 1));
		}
		for (int i = 0; i < eventBanners.size(); i++)
		{
			eventBanners.get(i).update(state, i < events.size() ? events.get(i) : null);
		}
		List<Boost> boosts = state.getBoosts();
		if (boosts.isEmpty())
		{
			eventBlock.remove(boostPanel);
		}
		else if (boostPanel.getParent() != eventBlock)
		{
			eventBlock.add(boostPanel);
		}
		List<Bounty> bounties = state.getBounties();
		for (int i = 0; i < cards.size(); i++)
		{
			cards.get(i).update(i < bounties.size() ? bounties.get(i) : null, state);
		}

		boostPanel.removeAll();
		if (boosts.size() > 1)
		{
			boostPanel.add(Ui.label("Active boosts", FontManager.getRunescapeBoldFont(), Ui.GOOD));
		}
		for (Boost boost : boosts)
		{
			String prefix = boosts.size() == 1 ? "Active boost: " : "";
			String text = prefix + String.format("%sx %s: %s left", formatMultiplier(boost.getMultiplier()),
				boost.getResource().getDisplayName(), Ui.formatPlaytime(boost.getRemainingTicks()));
			boostPanel.add(Ui.label(text, FontManager.getRunescapeSmallFont(), Ui.GOOD));
		}
		boostPanel.revalidate();
		boostPanel.repaint();
		eventPanel.revalidate();
		eventPanel.repaint();
		eventBlock.revalidate();
		eventBlock.repaint();

		completedLabel.setText("Bounties completed: " + state.getBountiesCompleted());
		expeditionPanel.update(state);
	}

	private static String formatMultiplier(double multiplier)
	{
		return multiplier == Math.rint(multiplier) ? String.valueOf((long) multiplier) : String.valueOf(multiplier);
	}
}

package com.osrssettlement.ui;

import com.osrssettlement.model.Bounty;
import com.osrssettlement.model.BountyRarity;
import com.osrssettlement.model.BountyType;
import com.osrssettlement.model.SettlementState;
import java.awt.BorderLayout;
import java.awt.Color;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.ProgressBar;

class BountyCard extends JPanel
{
	private final JLabel titleLabel = Ui.label("", FontManager.getRunescapeBoldFont(), ColorScheme.TEXT_COLOR);
	private final JLabel rarityLabel = Ui.label("", FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR);
	private final JLabel rewardLabel = Ui.label("", FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR);
	private final JLabel expiryLabel = Ui.label("", FontManager.getRunescapeSmallFont(), ColorScheme.MEDIUM_GRAY_COLOR);
	private final ProgressBar progressBar = new ProgressBar();
	private final JButton actionButton = new JButton();
	private int bountyId = -1;

	BountyCard(SettlementActions actions)
	{
		setLayout(new BorderLayout(0, 4));
		setBorder(new EmptyBorder(6, 6, 6, 6));
		rarityLabel.setOpaque(true);
		rarityLabel.setBorder(new EmptyBorder(1, 4, 1, 4));

		progressBar.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		progressBar.setForeground(ColorScheme.PROGRESS_INPROGRESS_COLOR);

		actionButton.setFocusPainted(false);
		actionButton.addActionListener(e ->
		{
			if (bountyId >= 0)
			{
				actions.claimBounty(bountyId);
			}
		});

		JPanel footer = new JPanel(new BorderLayout(0, 4));
		footer.setOpaque(false);
		footer.add(rewardLabel, BorderLayout.NORTH);
		footer.add(expiryLabel, BorderLayout.CENTER);
		footer.add(actionButton, BorderLayout.SOUTH);

		JPanel header = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
		header.setOpaque(false);
		JPanel rarityRow = new JPanel(new BorderLayout());
		rarityRow.setOpaque(false);
		rarityRow.add(rarityLabel, BorderLayout.EAST);
		header.add(rarityRow);
		header.add(titleLabel);
		add(header, BorderLayout.NORTH);
		add(progressBar, BorderLayout.CENTER);
		add(footer, BorderLayout.SOUTH);
	}

	void update(Bounty bounty, SettlementState state)
	{
		setVisible(bounty != null);
		if (bounty == null)
		{
			bountyId = -1;
			return;
		}

		bountyId = bounty.getId();
		titleLabel.setText(Ui.wrap(bounty.describe()));
		rarityLabel.setText(bounty.getRarity().getDisplayName());
		setRarityColors(bounty.getRarity());

		boolean delivery = bounty.getType() == BountyType.DELIVER;
		double progress = delivery
			? Math.min(bounty.getTarget(), Math.floor(state.getStock(bounty.getResource())))
			: bounty.getProgress();
		boolean ready = progress >= bounty.getTarget();
		progressBar.setMaximumValue((int) Math.min(Integer.MAX_VALUE, bounty.getTarget()));
		progressBar.setValue((int) Math.min(Integer.MAX_VALUE, Math.floor(progress)));
		String progressLabel = bounty.getType() == BountyType.SLAYER_DROPS
			? String.format("%,.1f / %,d", progress, bounty.getTarget())
			: String.format("%,.0f / %,d", progress, bounty.getTarget());
		progressBar.setCenterLabel(progressLabel);
		progressBar.setForeground(progress >= bounty.getTarget()
			? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_INPROGRESS_COLOR);

		rewardLabel.setText(Ui.wrap("Reward: " + bounty.getReward().describe()));
		rewardLabel.setForeground(bounty.isBlueprint() ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
		expiryLabel.setText(ready
			? "Ready to claim"
			: "Expires in " + Ui.formatPlaytime(Math.max(0, bounty.getExpiresAtPlaytime() - state.getPlaytimeTicks())) + " of play");

		actionButton.setText("Claim");
		actionButton.setToolTipText(delivery
			? String.format("Hands in %,d %s", bounty.getTarget(), bounty.getResource().getDisplayName())
			: null);
		actionButton.setVisible(ready);
		actionButton.setEnabled(ready);
	}

	private void setRarityColors(BountyRarity rarity)
	{
		switch (rarity)
		{
			case RARE:
				setBackground(new Color(45, 57, 69));
				rarityLabel.setBackground(new Color(58, 75, 92));
				break;
			case EPIC:
				setBackground(new Color(60, 49, 67));
				rarityLabel.setBackground(new Color(81, 65, 91));
				break;
			case COMMON:
			default:
				setBackground(new Color(58, 58, 58));
				rarityLabel.setBackground(new Color(77, 77, 77));
				break;
		}
	}
}

